:root {
  --porcelain: oklch(0.975 0.007 255);   /* page */
  --surface: oklch(0.93 0.014 255);      /* quiet panels */
  --ink: oklch(0.23 0.035 264);          /* body text */
  --muted: oklch(0.46 0.035 264);        /* secondary text, 6.7:1 on porcelain */
  --line: oklch(0.62 0.04 260);          /* rules, 3.4:1 on porcelain */
  --cobalt: oklch(0.37 0.15 264);        /* the glaze: hero, footer, marks */
  --cobalt-deep: oklch(0.30 0.12 264);
  --slip: oklch(0.965 0.01 255);         /* text on cobalt */
  --slip-muted: oklch(0.84 0.04 260);    /* secondary text on cobalt, 6.6:1 */
  --celadon: oklch(0.82 0.085 170);      /* the one accent: primary action */
  --celadon-hover: oklch(0.88 0.075 170);
  --ring: var(--cobalt);

  --font: "Bricolage Grotesque", ui-sans-serif, system-ui, -apple-system, "Segoe UI", sans-serif;

  /* type scale, ratio 1.333 */
  --step-0: 1.0625rem;
  --step-1: 1.3rem;
  --step-2: 1.75rem;
  --step-3: clamp(2rem, 1.5rem + 2vw, 2.75rem);
  --step-4: clamp(2.5rem, 1.6rem + 4.2vw, 5.25rem);

  --space-1: 0.5rem;
  --space-2: 1rem;
  --space-3: 1.5rem;
  --space-4: 2.5rem;
  --space-5: 4rem;
  --space-6: clamp(4.5rem, 3rem + 6vw, 8rem);

  --radius-control: 999px;
  --ease-out: cubic-bezier(0.25, 1, 0.5, 1); /* quart */
}

.cobalt {
  --ring: var(--slip);
  background: var(--cobalt);
  color: var(--slip);
}

*, *::before, *::after { box-sizing: border-box; }

html {
  -webkit-text-size-adjust: 100%;
  scroll-behavior: smooth;
}

body {
  margin: 0;
  background: var(--porcelain);
  color: var(--ink);
  font-family: var(--font);
  font-size: var(--step-0);
  line-height: 1.6;
  font-optical-sizing: auto;
}

::selection { background: var(--celadon); color: var(--ink); }

img { display: block; max-width: 100%; height: auto; }

h1, h2, h3 {
  margin: 0;
  line-height: 1.08;
  text-wrap: balance;
  font-weight: 800;
}
h2 { font-size: var(--step-3); letter-spacing: -0.02em; }
h3 { font-size: var(--step-2); line-height: 1.15; font-weight: 600; letter-spacing: -0.01em; }
p { margin: 0; text-wrap: pretty; }

a { color: inherit; text-underline-offset: 0.2em; text-decoration-thickness: 0.08em; }

:focus-visible {
  outline: 3px solid var(--ring);
  outline-offset: 3px;
  border-radius: 4px;
}

.wrap {
  width: 100%;
  max-width: 76rem;
  margin-inline: auto;
  padding-inline: clamp(1.25rem, 4vw, 3rem);
}

.visually-hidden {
  position: absolute;
  width: 1px; height: 1px;
  overflow: hidden;
  clip-path: inset(50%);
  white-space: nowrap;
}

.defs { position: absolute; width: 0; height: 0; overflow: hidden; }

.skip {
  position: absolute;
  top: 0.5rem; left: 0.5rem;
  z-index: 10;
  padding: 0.75rem 1rem;
  background: var(--slip);
  color: var(--ink);
  font-weight: 600;
  transform: translateY(-200%);
}
.skip:focus-visible { transform: none; --ring: var(--celadon); }

/* ---------- buttons ---------- */

.button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 3rem;
  padding: 0.75rem 1.5rem;
  border-radius: var(--radius-control);
  background: var(--celadon);
  color: var(--ink);
  font-weight: 600;
  text-decoration: none;
  touch-action: manipulation;
  transition: background-color 180ms var(--ease-out), transform 100ms var(--ease-out);
}
.button:active { transform: scale(0.97); background: var(--celadon-hover); }

.button--ink {
  background: var(--cobalt);
  color: var(--slip);
}
.button--ink:active { background: var(--cobalt-deep); }

@media (hover: hover) {
  .button:hover { background: var(--celadon-hover); }
  .button--ink:hover { background: var(--cobalt-deep); }
}

.text-link {
  display: inline-flex;
  align-items: center;
  min-height: 3rem;
  font-weight: 600;
}

/* ---------- header ---------- */

.nav {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-1) var(--space-3);
  padding-block: var(--space-2);
}

.wordmark {
  display: inline-flex;
  align-items: center;
  gap: 0.6rem;
  min-height: 2.75rem;
  font-size: var(--step-1);
  font-weight: 800;
  letter-spacing: -0.01em;
  text-decoration: none;
}
.wordmark__mark { width: 1.1rem; height: 1.45rem; fill: var(--celadon); }

.nav__links {
  display: flex;
  flex-wrap: wrap;
  gap: 0 var(--space-1);
  margin: 0;
  padding: 0;
  list-style: none;
}
.nav__links a {
  display: inline-flex;
  align-items: center;
  min-height: 2.75rem;
  padding-inline: 0.6rem;
  color: var(--slip);
  font-weight: 600;
  text-decoration-color: transparent;
  transition: text-decoration-color 180ms var(--ease-out);
}
.nav__links a:active { text-decoration-color: currentColor; }
@media (hover: hover) {
  .nav__links a:hover { text-decoration-color: currentColor; }
}

/* ---------- hero ---------- */

.hero__inner {
  display: grid;
  gap: var(--space-4);
  align-items: center;
  padding-block: var(--space-4) var(--space-6);
}

.hero__copy { max-width: 36rem; }

.hero h1 {
  font-size: var(--step-4);
  letter-spacing: -0.035em;
  line-height: 1;
}

.hero__lede {
  margin-top: var(--space-3);
  max-width: 34rem;
  color: var(--slip-muted);
  font-size: var(--step-1);
  line-height: 1.55;
}

.hero__actions {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: var(--space-2) var(--space-3);
  margin-top: var(--space-4);
}

.hero__photo {
  margin: 0;
  justify-self: center;
  width: min(100%, 24rem);
}

/* entrance: movement only, never visibility */
.hero__copy > * { animation: rise 700ms var(--ease-out) both; }
.hero__copy > :nth-child(2) { animation-delay: 80ms; }
.hero__copy > :nth-child(3) { animation-delay: 160ms; }
@keyframes rise { from { transform: translateY(0.75rem); } }

/* ---------- the signature: vessel frames ---------- */

.vessel { width: 100%; object-fit: cover; background: var(--surface); }
.vessel--jar { aspect-ratio: 4 / 5; clip-path: url(#clip-jar); }
.vessel--beaker { aspect-ratio: 1; clip-path: url(#clip-beaker); }
.vessel--bowl { aspect-ratio: 1; clip-path: url(#clip-bowl); }
.vessel--platter { aspect-ratio: 9 / 7; clip-path: url(#clip-platter); }

/* ---------- workshops ---------- */

.workshops { padding-block: var(--space-6); }

.section-head {
  display: grid;
  gap: var(--space-2);
  max-width: 42rem;
  margin-bottom: var(--space-5);
}
.section-head p { color: var(--muted); }

.workshop-list {
  margin: 0;
  padding: 0;
  list-style: none;
  border-bottom: 1px solid var(--line);
}

.workshop {
  display: grid;
  grid-template-columns: 3.5rem 1fr;
  gap: var(--space-2) var(--space-3);
  padding-block: var(--space-4);
  border-top: 1px solid var(--line);
}

.workshop__mark {
  width: 3.5rem;
  height: 4rem;
  fill: var(--cobalt);
}
.workshop__mark--pair { height: 3rem; margin-top: 1rem; }

.workshop__body { display: grid; gap: var(--space-1); max-width: 38rem; }
.workshop__when { color: var(--muted); font-weight: 600; }

.workshop__book {
  grid-column: 2;
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: var(--space-2) var(--space-3);
}

.price { display: flex; align-items: baseline; gap: 0.4rem; }
.price__amount {
  font-size: var(--step-3);
  font-weight: 800;
  letter-spacing: -0.02em;
  line-height: 1;
  font-variant-numeric: tabular-nums;
}
.price__unit { color: var(--muted); }

.booking-note {
  margin-top: var(--space-3);
  max-width: 42rem;
  color: var(--muted);
}
.booking-note a { color: var(--ink); font-weight: 600; overflow-wrap: anywhere; }

/* ---------- studio ---------- */

.studio {
  padding-block: var(--space-6);
  background: var(--surface);
}

.studio__inner { display: grid; gap: var(--space-5); }

.studio__copy { display: grid; gap: var(--space-2); max-width: 30rem; align-content: start; }
.studio__copy h2 { margin-bottom: var(--space-1); }

.gallery {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--space-4) var(--space-3);
  align-items: end;
}
.gallery__item { margin: 0; display: grid; gap: 0.75rem; }
.gallery__item--tall,
.gallery__item--wide { grid-column: 1 / -1; }
.gallery__item figcaption { color: var(--muted); font-size: 0.95rem; }

/* ---------- footer ---------- */

.site-footer { background: var(--cobalt-deep); }

.footer__inner {
  display: grid;
  gap: var(--space-4);
  padding-block: var(--space-6) var(--space-5);
}
.footer__lead { display: grid; gap: var(--space-3); justify-items: start; }
.footer__block { font-style: normal; display: grid; gap: var(--space-1); }
.footer__block h3 { font-size: var(--step-1); }
.footer__block p { color: var(--slip-muted); }
.footer__block a { color: var(--slip); overflow-wrap: anywhere; }
.footer__block a { display: inline-block; padding-block: 0.6rem; }

.footer__base {
  padding-block: var(--space-3);
  border-top: 1px solid oklch(0.62 0.07 262); /* 3.2:1 on cobalt-deep */
  color: var(--slip-muted);
  font-size: 0.95rem;
}

/* ---------- wider screens ---------- */

@media (min-width: 40rem) {
  .gallery__item--tall { grid-column: 1; grid-row: 1 / span 2; }
  .gallery__item--wide { grid-column: 1 / -1; }
  .gallery { grid-template-columns: 1.3fr 1fr; }
}

@media (min-width: 56rem) {
  .hero__inner { grid-template-columns: 1.15fr 0.85fr; padding-block: var(--space-5) var(--space-6); }
  .hero__photo { justify-self: end; width: min(100%, 26rem); }

  .workshop {
    grid-template-columns: 4.5rem minmax(0, 1fr) 16rem;
    align-items: start;
  }
  .workshop__mark { width: 4.5rem; height: 5rem; }
  .workshop__mark--pair { height: 3.75rem; margin-top: 1.25rem; }
  .workshop__book {
    grid-column: 3;
    flex-direction: column;
    align-items: flex-start;
  }

  .studio__inner { grid-template-columns: minmax(0, 0.8fr) minmax(0, 1.2fr); align-items: start; }
  .studio__copy { position: sticky; top: var(--space-4); }

  .footer__inner { grid-template-columns: 1.4fr repeat(3, 1fr); }
}

@media (prefers-reduced-motion: reduce) {
  html { scroll-behavior: auto; }
  .hero__copy > * { animation: none; }
  .button { transition: background-color 120ms linear; }
  .button:active { transform: none; }
}

@media (forced-colors: active) {
  .button { border: 2px solid ButtonText; }
  .workshop__mark, .wordmark__mark { fill: CanvasText; }
}

