const f=(n)=>n<=0.0031308?12.92*n:1.055*Math.pow(n,1/2.4)-0.055;
const o=(L,C,H)=>{const h=H*Math.PI/180,a=C*Math.cos(h),b=C*Math.sin(h);
  const l=(L+0.3963377774*a+0.2158037573*b)**3, m=(L-0.1055613458*a-0.0638541728*b)**3,
        s=(L-0.0894841775*a-1.2914855480*b)**3;
  return [ 4.0767416621*l-3.3077115913*m+0.2309699292*s,
          -1.2684380046*l+2.6097574011*m-0.3413193965*s,
          -0.0041960863*l-0.7034186147*m+1.7076147010*s]
        .map(v=>Math.round(Math.min(1,Math.max(0,f(v)))*255));};
const lum=([r,g,b])=>{const c=[r,g,b].map(v=>{v/=255;return v<=0.03928?v/12.92:((v+0.055)/1.055)**2.4;});
  return 0.2126*c[0]+0.7152*c[1]+0.0722*c[2];};
const ratio=(A,B)=>{const [x,y]=[lum(A),lum(B)].sort((p,q)=>q-p);return +((x+0.05)/(y+0.05)).toFixed(2);};
const T={porcelain:o(0.975,0.007,255),surface:o(0.93,0.014,255),cobalt:o(0.37,0.15,264),cobaltDeep:o(0.30,0.12,264),
ink:o(0.23,0.035,264),muted:o(0.46,0.035,264),slip:o(0.965,0.01,255),slipMuted:o(0.84,0.04,260),celadon:o(0.82,0.085,170),line:o(0.62,0.04,260)};
for(const k in T) console.log(k, T[k].map(v=>v.toString(16).padStart(2,'0')).join(''));
const p=[['ink','porcelain'],['muted','porcelain'],['ink','surface'],['muted','surface'],['cobalt','porcelain'],['slip','cobalt'],['slipMuted','cobalt'],['ink','celadon'],['celadon','cobalt'],['line','porcelain'],['cobalt','surface'],['slip','cobaltDeep'],['slipMuted','cobaltDeep'],['celadon','cobaltDeep']];
for(const [a,b] of p) console.log(a,'on',b,ratio(T[a],T[b]));
